package com.termux.app.workspace;
import android.app.Application;import android.os.Looper;import android.view.View;import com.termux.R;import com.termux.app.TermuxActivity;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import java.util.concurrent.atomic.*;import java.io.File;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentHistoryCursorRegressionTest {
 TermuxActivity a;AgentChatUi ui;File marker;AtomicBoolean ready=new AtomicBoolean(),failPage=new AtomicBoolean();AtomicInteger previousReads=new AtomicInteger();
 void idle()throws Exception{Thread.sleep(15);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 void load()throws Exception{Method m=AgentChatUi.class.getDeclaredMethod("load",boolean.class);m.setAccessible(true);m.invoke(ui,false);for(int n=0;n<20;n++)idle();}
 JSONObject row(String key)throws Exception{return new JSONObject().put("key",key).put("message",key).put("kind","text").put("body",key);}
 void run(String agent,boolean retry)throws Exception{
  a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);Field terminal=TermuxActivity.class.getDeclaredField("mTerminalView");terminal.setAccessible(true);terminal.set(a,a.findViewById(R.id.terminal_view));WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=agent.equals("codex")?"codex":"ubuntu";p.claudeAgent=agent.equals("claude");p.geminiAgent=agent.equals("gemini");p.aiAgent=agent.equals("opencode")?"opencode":"";
  if(agent.equals("codex")){marker=CodexChatControl.marker(a.getFilesDir(),p);marker.getParentFile().mkdirs();marker.createNewFile();}
  ui=new AgentChatUi(a,()->p,()->true,(profile,q)->{assertTrue(q.optString("op"),q.optString("op").equals("chat-snapshot")||q.optString("op").equals("status"));if(q.has("cursor")){assertEquals("NATIVE_CURSOR_1",q.getString("cursor"));previousReads.incrementAndGet();if(failPage.getAndSet(false))throw new java.io.IOException("Artificial page failure");return new JSONObject().put("ok",true).put("nativeChat",true).put("connected",true).put("session",p.id).put("partialHistory",true).put("older",JSONObject.NULL).put("rows",new JSONArray().put(row("older-original")));}return new JSONObject().put("ok",true).put("nativeChat",true).put("connected",ready.get()).put("session",p.id).put("partialHistory",true).put("older",ready.get()?"NATIVE_CURSOR_1":JSONObject.NULL).put("rows",ready.get()?new JSONArray().put(row("latest-user")).put(row("latest-assistant")):new JSONArray());});
  load();Field vf=AgentChatUi.class.getDeclaredField("view");vf.setAccessible(true);AgentChatView view=(AgentChatView)vf.get(ui);assertEquals(View.GONE,view.older.getVisibility());ready.set(true);load();assertEquals("Late real cursor must expose the button",View.VISIBLE,view.older.getVisibility());assertTrue(ui.projectSource().hasOlder());failPage.set(retry);view.older.performClick();for(int n=0;n<30;n++)idle();if(retry){assertEquals(View.VISIBLE,view.older.getVisibility());assertTrue(view.older.isEnabled());assertTrue(view.older.getText().toString().contains("Retry")||view.older.getText().toString().contains("Повторить"));view.older.performClick();for(int n=0;n<30;n++)idle();}assertEquals(retry?2:1,previousReads.get());assertEquals(View.GONE,view.older.getVisibility());Field rf=AgentChatUi.class.getDeclaredField("rows");rf.setAccessible(true);assertTrue(((java.util.Map<?,?>)rf.get(ui)).containsKey("older-original"));load();assertEquals("Ordinary head polls must not reopen an exhausted cursor",View.GONE,view.older.getVisibility());assertTrue(((java.util.Map<?,?>)rf.get(ui)).containsKey("older-original"));
 }
 @After public void close(){if(ui!=null)ui.close();if(marker!=null)marker.delete();if(a!=null)a.finish();}
 @Test public void codexLateCursorExposesButtonAndLoadsOriginalRows()throws Exception{run("codex",false);}
 @Test public void claudeLateCursorExposesButtonAndLoadsOriginalRows()throws Exception{run("claude",false);}
 @Test public void geminiLateCursorExposesButtonAndLoadsOriginalRows()throws Exception{run("gemini",false);}
 @Test public void openCodeLateCursorExposesButtonAndLoadsOriginalRows()throws Exception{run("opencode",false);}
 @Test public void codexFailedPageKeepsButtonAndRetryDoesNotLoseRows()throws Exception{run("codex",true);}
}
